-- blogs
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (1, '55th Anniversary of Asia Asset Finance PLC', '55th-anniversary-of-asia-asset-finance-plc', 'Event coverage in Jaffna and Kilinochchi.', 'Event coverage', '<p>Event coverage of the 55th anniversary of Asia Asset Finance PLC, across events in Jaffna and Kilinochchi.</p>', 12, 0, 'published', 1, '2025-01-01 09:00:00', '2025-01-01 09:00:00', '2025-01-01 09:00:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (2, 'Nadiyas textile brand introduction video', 'nadiyas-textile-brand-introduction-video', 'Behind the scenes of a brand story film.', 'Brand film', '<p>Behind the scenes of the brand introduction film for Nadiyas textiles.</p><p>A brand story film gives a business a single piece of video that explains who they are, and can be cut down into short-form clips for social media.</p>', 11, 0, 'published', 1, '2025-12-21 09:00:00', '2025-12-21 09:00:00', '2025-12-21 09:00:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (3, 'Mahaposa Commercial Advertisement', 'mahaposa-commercial-advertisement', 'Behind the scenes of a commercial advertisement shoot.', 'Commercial', '<p>Behind the scenes of the Mahaposa commercial advertisement, from setup on location to the final takes.</p><p>Commercial work like this runs through our full production pipeline: concept, shoot, edit and delivery in the formats each platform needs.</p>', 10, 0, 'published', 1, '2025-12-25 09:00:00', '2025-12-25 09:00:00', '2025-12-25 09:00:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (4, 'India\'s 77th Republic Day Celebrations', 'india-s-77th-republic-day-celebrations', 'Event coverage for the Consulate General of India in Jaffna.', 'Event coverage', '<p>Yarl Creators provided event coverage for the Consulate General of India in Jaffna during the 77th Republic Day celebrations.</p><p>The team handled photography and video across the ceremony and the cultural programme that followed.</p><figure><img src="/media/9" alt=""></figure>', 8, 0, 'published', 1, '2026-01-26 09:00:00', '2026-01-26 09:00:00', '2026-01-26 09:00:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (5, 'Opening Ceremony of the DP Logistics Multi-User 3PL Warehouse', 'opening-ceremony-of-the-dp-logistics-multi-user-3pl-warehouse', 'Behind the scenes: commercial photography and videography.', 'Event coverage', '<p>Our crew covered the opening ceremony of the DP Logistics multi-user 3PL warehouse with commercial photography and videography.</p><p>The brief was a complete record of the day: arrivals, the formal opening and the facility itself, delivered as an edited film and a photo set the client could use across its own channels.</p>', 7, 1, 'published', 1, '2026-01-28 09:00:00', '2026-01-28 09:00:00', '2026-01-28 09:00:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (6, 'Empowering the Next Wave of Creators: University of Jaffna Workshops & Partnerships', 'empowering-next-wave-creators-workshops-partnerships', 'How our hands-on Wildlife Photography Workshop at the University of Jaffna and creative partnerships with Rajadevan Rajangam and V Screen Entertainment are building a thriving creator ecosystem.', 'Workshops & Partnerships', '<p>The Yarl Creators Workshops &amp; Partnerships initiative was built to foster creativity, collaboration, and innovation among aspiring creators worldwide.</p>\n<p>Through our hands-on workshops—including the Wildlife Photography Workshop hosted with the University of Jaffna—participants gain practical, field-tested skills in photography, digital marketing, content creation, and branding.</p>\n<p>Meanwhile, our strategic partnerships with industry leaders like Rajadevan Rajangam and V Screen Entertainment open new doors for regional talent to collaborate on large-scale media productions and cross-border storytelling initiatives.</p>', 14, 0, 'published', 1, '2026-01-28 14:15:00', '2026-01-28 14:15:00', '2026-11-10 08:12:49');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (7, 'Inside Our Commercial Photography & Videography Workflow for Leading Brands', 'inside-commercial-photography-videography-workflow', 'A behind-the-scenes look at how we shoot and edit commercial campaigns for Luxmy Food Products, Thalir Seed Funding Awarding, David Pieris Group of Companies, and luxury hospitality venues.', 'Visual Content Creation', '<p>Great commercial visuals do more than document a product—they evoke emotion and build instant credibility.</p>\n<p>In our Visual Content Creation division, we divide every production into two specialized phases:</p>\n<ol><li>Commercial Photography &amp; Videography: Whether capturing culinary textures for Luxmy Food Products, corporate milestones at the Thalir Seed Funding Awarding with David Pieris Group of Companies, or architectural elegance at Yarl Royal Palace and Tilko Blue Ocean, lighting and composition are tailored to the brand\'s core identity.</li></ol>\n<ol><li>Video Editing Services: In post-production, our visual editors craft pacing, sound design, and color grading that turn raw camera files into high-converting digital assets across YouTube, Instagram, and broadcast channels.</li></ol>', 13, 1, 'published', 1, '2026-02-10 10:30:00', '2026-02-10 10:30:00', '2026-02-10 10:30:00');
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `category`, `content`, `cover_id`, `featured`, `status`, `reading_minutes`, `published_at`, `created_at`, `updated_at`) VALUES (8, 'Grow Local, Reach Global: How Visual Storytelling Transforms Jaffna Brands', 'grow-local-reach-global-visual-storytelling-jaffna', 'Discover how Yarl Creators empowers Northern Province businesses to scale across 6+ countries through cinema-grade documentaries, commercial photography, and digital brand architecture.', 'Creative Storytelling', '<p>Founded in 2022 in Keerimalai, Jaffna, Yarl Creators set out with a bold mission: to help local entrepreneurs harness the power of visual media and technology so their stories resonate globally.</p>\n<p>From commercial product photography for Luxmy Food Products to hospitality visual campaigns for Yarl Royal Palace and Tilko Blue Ocean, high-trust visual assets are the bridge between regional excellence and international diaspora markets.</p>\n<p>Our three-pillar framework combines:</p><ol><li>Authentic Documentary &amp; Brand Narratives that highlight craft and heritage.</li><li>Commercial Photography &amp; Precision Post-Production that elevate perceived product value.</li><li>Full-Stack Digital Presence — pairing custom responsive web platforms with data-driven social media management.</li></ol>', 15, 1, 'published', 1, '2026-02-18 09:00:00', '2026-02-18 09:00:00', '2026-11-10 08:13:50');

